#!/usr/bin/env bash

set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$script_dir"

echo "Cleaning React Native build artifacts..."

# Library build output
rm -rf \
  lib \
  dist \
  build \
  .test-dist \
  .build \
  .swiftpm \
  .gradle \
  .cache \
  .turbo \
  .expo \
  coverage \
  vendor \
  .metro-cache \
  .tmp \
  .metro-health-check*

# React Native Windows Codegen output generated by the consuming Windows build
rm -rf \
  windows/FFmpegKitExtended/codegen \
  windows/FFmpegKitExtended/obj \
  windows/FFmpegKitExtended/x64 \
  windows/FFmpegKitExtended/x86 \
  windows/FFmpegKitExtended/bin \
  windows/FFmpegKitExtended/Generated\ Files \
  windows/FFmpegKitExtended/AppPackages \
  windows/FFmpegKitExtended/.vs

# Library Android / CMake
rm -rf \
  android/.gradle \
  android/.cxx \
  android/.externalNativeBuild \
  android/.kotlin \
  android/build \
  android/app/.cxx \
  android/app/.externalNativeBuild \
  android/app/build

# Library Apple platform build products and dependency outputs
rm -rf \
  ios/build \
  ios/Pods \
  ios/.symlinks \
  ios/DerivedData \
  ios/.build \
  ios/.swiftpm \
  appletvos/build \
  appletvos/Pods \
  appletvos/.symlinks \
  appletvos/DerivedData \
  appletvos/.build \
  appletvos/.swiftpm \
  macos/build \
  macos/Pods \
  macos/.symlinks \
  macos/DerivedData \
  macos/.build \
  macos/.swiftpm

# Example caches
rm -rf \
  example/build \
  example/dist \
  example/.test-dist \
  example/.build \
  example/.swiftpm \
  example/.cache \
  example/.turbo \
  example/.expo \
  example/.metro-cache \
  example/.tmp \
  example/coverage \
  example/.metro-health-check* \
  example/.macos-runtime/.metro-cache \
  example/.macos-runtime/.tmp \
  example/.macos-runtime/coverage \
  example/.appletvos-runtime/.metro-cache \
  example/.appletvos-runtime/.tmp \
  example/.appletvos-runtime/coverage \
  example/.windows-runtime/.metro-cache \
  example/.windows-runtime/.tmp \
  example/.windows-runtime/coverage

# Example Android / Gradle / CMake
rm -rf \
  example/android/.gradle \
  example/android/.cxx \
  example/android/.externalNativeBuild \
  example/android/.kotlin \
  example/android/build \
  example/android/app/.cxx \
  example/android/app/.externalNativeBuild \
  example/android/app/build

# Example Windows
rm -rf \
  example/windows/build \
  example/windows/x64 \
  example/windows/FFmpegKitExtendedExample/bin \
  example/windows/FFmpegKitExtendedExample/obj \
  example/windows/FFmpegKitExtendedExample.Package/bin \
  example/windows/FFmpegKitExtendedExample.Package/obj \
  example/windows/FFmpegKitExtendedExample.Package/AppPackages \
  example/windows/FFmpegKitExtendedExample/Generated\ Files \
  example/windows/FFmpegKitExtendedExample.Package/Generated\ Files \
  example/.windows-runtime \
  example/windows/vendor \
  example/windows/packages \
  example/windows/.vs

# Example iOS
rm -rf \
  example/ios/build \
  example/ios/Pods \
  example/ios/.symlinks \
  example/ios/DerivedData \
  example/ios/.build \
  example/ios/.swiftpm

# Example Apple tvOS
rm -rf \
  example/appletvos/build \
  example/appletvos/Pods \
  example/appletvos/.symlinks \
  example/appletvos/DerivedData \
  example/appletvos/.build \
  example/appletvos/.swiftpm \
  example/.appletvos-runtime

# Example macOS
rm -rf \
  example/macos/build \
  example/macos/Pods \
  example/macos/.symlinks \
  example/macos/DerivedData \
  example/macos/.build \
  example/macos/.swiftpm \
  example/.macos-runtime

# The Web build and prepare-web output are staged outside the usual build dir.
rm -rf \
  example/public/ffmpeg-kit-extended/wasm
if [[ -d node_modules && ! -L node_modules ]]; then
  rm -rf node_modules/.cache node_modules/.vite
fi
if [[ -d example/node_modules && ! -L example/node_modules ]]; then
  rm -rf example/node_modules/.cache example/node_modules/.vite
fi

# CocoaPods and MSBuild outputs can also create workspaces/logs outside build/.
for platform_dir in ios appletvos macos example/ios example/appletvos example/macos; do
  if [[ -d "$platform_dir" ]]; then
    find "$platform_dir" -type d -name '*.xcworkspace' -prune -exec rm -rf {} +
  fi
done
if [[ -d example/windows ]]; then
  find example/windows -type d \
    \( -name codegen -o -name bin -o -name obj -o -name x64 -o -name x86 \
       -o -name AppPackages -o -name 'Generated Files' \) \
    -prune -exec rm -rf {} +
  find example/windows -type f \( -name '*.binlog' -o -name '*.err' -o -name '*.wrn' \) -delete
fi

# Compiler outputs and generated JS bundles, excluding dependencies and Git.
find . \
  \( -path './.git' -o -path '*/node_modules' \) -prune -o \
  -type f \( -name '*.tsbuildinfo' -o -name '*.jsbundle' \) \
  -exec rm -f {} +

if [[ $# -gt 0 ]] && [[ -n "$1" && "$1" == "full" ]]; then
  echo "Full clean mode enabled. Removing installed dependency trees and package-manager caches..."
  # Keep package, Pod, and native package lockfiles for reproducible rebuilds.
  rm -rf node_modules
  rm -rf example/node_modules
  rm -rf \
    .npm example/.npm \
    .pnpm-store example/.pnpm-store \
    .yarn/cache .yarn/unplugged example/.yarn/cache example/.yarn/unplugged
  rm -f \
    .pnp.* example/.pnp.* \
    .yarn/build-state.yml .yarn/install-state.gz \
    example/.yarn/build-state.yml example/.yarn/install-state.gz
fi

echo "Clean complete."
echo
echo "Rebuild the library:"
echo "  npm run prepare"
echo
echo "Rebuild examples:"
echo "  ./build.sh android"
echo "  ./build.sh ios"
echo "  ./build.sh appletvos"
echo "  ./build.sh macos"
echo "  ./build.sh windows"
